// Generates src/engine/index.ts: imports every engine module so that each class registers
// itself in the registry T (see docs/PORTING.md, "Module cycles").
import { readdirSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, sep } from 'node:path';

const root = 'src/engine';
const files = [];
(function walk(dir) {
  for (const f of readdirSync(dir).sort()) {
    const p = join(dir, f);
    if (statSync(p).isDirectory()) walk(p);
    else if (f.endsWith('.ts') && p !== join(root, 'index.ts')) files.push(p);
  }
})(root);
const lines = [
  '// Generated by scripts/gen-engine-index.mjs. Do not edit.',
  '// Loads every engine module so that all classes are registered in the registry T.',
  '',
  ...files.map((f) => `import './${relative(root, f).split(sep).join('/').replace(/\.ts$/, '.js')}';`),
  '',
  "export { T } from './registry.js';",
  '',
];
writeFileSync(join(root, 'index.ts'), lines.join('\n'));
console.log(`${files.length} modules`);
